/*
 * NETWORK_$WRITE - page out `count` pages to the node that backs them
 *
 * Original address: 0x00E0FAE6 (SAU2 map)
 * Size: 290 bytes (0x00E0FAE6 .. 0x00E0FC07)
 * Generated by: Claude Opus 5.5
 *
 * Callers: area_$rpmap_get (0x00E074FA), pmap_$write_page (0x00E130DC).
 * A5 = 0xE248FC (`lea`, 0x00E0FAEE).
 *
 * Frame (link.w A6,-0x110): (0x8) node_addr, (0xc) req, (0x10) ppn (D5),
 * (0x14) pkt_size, (0x16) count (D3, zero-extended), (0x18) dtv_low (A3),
 * (0x1c) dtm (A2), (0x20) status (A4).  Locals: (-0x48) the 0x2A-byte
 * page-out request, (-0x100) the reply buffer, (-0x10c) the reply info,
 * (-0x10a)/(-0x108) the length/address pair for the checksum.
 *
 * Blocks:
 *   0x00E0FB04-0x00E0FB18  chunk (D2w) = NETWORK_$GET_PKT_SIZE(node_addr,
 *                          pkt_size)
 *   0x00E0FB1A-0x00E0FB3E  request = { type 4, flag 0xFF, version 8,
 *                          req = *req (8 longwords) }; first (D4b) = 0xFF
 *   0x00E0FB42-0x00E0FB44  D5 = ppn << 10, the page's physical address
 *   0x00E0FB48-0x00E0FB6A  NETWORK_$DO_CHKSUM -> request.chksum =
 *                          network_$page_chksum(&pa) (a second argument,
 *                          &chunk, is pushed and never read); else 0
 *   0x00E0FB6E             NETWORK_$WRITE_CALL_CNT++
 *   0x00E0FB72-0x00E0FB9A  network_$do_request(node_addr, &request, 0x2A,
 *                          D5, chunk, 0, &reply, &info, status); failed ->
 *                          return
 *   0x00E0FB9C-0x00E0FBE2  first reply only: version >= 6 -> *dtv_low =
 *                          dtm_low, *dtm = reply clock; >= 4 -> *dtv_low =
 *                          dtm_low, *dtm = (dtm_high, *dtv_low); older ->
 *                          (dtm_bits << 8) & 0xF800 for both low words.
 *                          The request's flag byte stays 0xFF.
 *   0x00E0FBE6-0x00E0FBFA  D5 += chunk; request.req.page_num += chunk >> 10;
 *                          D3 -= chunk >> 10; loop while D3 > 0 (signed)
 */

#include "network/network_internal.h"

void NETWORK_$WRITE(void *node_addr, network_$page_request_t *req,
                    uint32_t ppn, uint16_t pkt_size, uint16_t count,
                    uint16_t *dtv_low, clock_t *dtm, status_$t *status)
{
    uint16_t chunk;                     /* D2w */
    int8_t first;                       /* D4b */
    int32_t remaining;                  /* D3 */
    uint32_t pa;                        /* D5 */
    network_$pagout_rqst_t request;     /* (-0x48,A6) */
    union {
        network_$pagout_reply_t pagout;
        uint8_t bytes[0xB8];
    } reply;                            /* (-0x100,A6) */
    int16_t info[6];                    /* (-0x10c,A6) */
    uint16_t chk_len;                   /* (-0x10a,A6) */
    uint32_t chk_pa;                    /* (-0x108,A6) */
    uint16_t low;
    uint32_t pages;

    /* 0x00E0FB04-0x00E0FB18 */
    chunk = NETWORK_$GET_PKT_SIZE((uint32_t *)node_addr, pkt_size);

    /* 0x00E0FB1A-0x00E0FB3E */
    first = (int8_t)0xFF;
    remaining = (int32_t)count;
    request.type = 4;
    request.flag = first;
    request.version = 8;
    request.req = *req;

    /* 0x00E0FB42-0x00E0FB44 */
    pa = ppn << 10;

    do {
        /* 0x00E0FB48-0x00E0FB6A */
        if ((int8_t)NETWORK_$DO_CHKSUM < 0) {
            chk_len = chunk;
            chk_pa = pa;
            (void)chk_len;
            request.chksum = network_$page_chksum(&chk_pa);
        } else {
            request.chksum = 0;
        }

        /* 0x00E0FB6E */
        NETWORK_$WRITE_CALL_CNT++;

        /* 0x00E0FB72-0x00E0FB9A */
        network_$do_request(node_addr, &request, 0x2A, pa, chunk, 0,
                            &reply, info, status);
        if (*status != status_$ok) {
            return;
        }

        /* 0x00E0FB9C-0x00E0FBE2 */
        if (first < 0) {
            first = 0;
            if (reply.pagout.version >= 6) {
                *dtv_low = reply.pagout.dtm_low;            /* 0x00E0FBAA */
                dtm->high = reply.pagout.clock.high;
                dtm->low = reply.pagout.clock.low;
            } else if (reply.pagout.version >= 4) {
                *dtv_low = reply.pagout.dtm_low;            /* 0x00E0FBC2 */
                dtm->high = reply.pagout.u.f.dtm_high;
                dtm->low = *dtv_low;
            } else {
                /* 0x00E0FBD0-0x00E0FBE2 */
                low = (uint16_t)(((uint16_t)reply.pagout.u.f.dtm_bits << 8)
                                 & 0xF800);
                *dtv_low = low;
                dtm->high = reply.pagout.u.f.dtm_high;
                dtm->low = low;
            }
        }

        /* 0x00E0FBE6-0x00E0FBFA */
        pa += (uint32_t)chunk;
        pages = (uint32_t)chunk >> 10;
        request.req.page_num += pages;
        remaining -= (int32_t)pages;
    } while (remaining > 0);
}
